UPDATE public.page_content_overrides 
SET sections = '[{"tag": "h1", "content": "בוגרת לימודי רפואה באוניברסיטת בן גוריון בנגב והתמחות ברפואת ילדים בבית החולים שניידר. את תת ההתמחות באלרגיה ואימונולוגיה קלינית השלימה בארה\"ב בבית החולים Vanderbilt University Medical Center ושבה כרופאה בכירה למכון האלרגיה בבית החולים שניידר לרפואת ילדים.", "heading": "מרפאת אלרגיה - ד״ר אנה ברמלי"}, {"tag": "h2", "content": "\u00a0בוגרת לימודי רפואה באוניברסיטת בן גוריון בנגב והתמחות ברפואת ילדים בבית החולים שניידר. את תת ההתמחות באלרגיה ואימונולוגיה קלינית השלימה בארה\"ב בבית החולים Vanderbilt University Medical Center ושבה כרופאה בכירה למכון האלרגיה בבית החולים שניידר לרפואת ילדים.", "heading": "כמה מילים על ד\"ר אנה ברמלי"}, {"tag": "h2", "content": "אבחון וטיפול באלרגיה למזון בילדים, אסתמה אלרגית וקוצר נשימה, אורטיקריה, אלרגיה לתרופות ואנטיביוטיקה, אלרגיה לדבורים ואלרגיות עונתיות.", "heading": "שירותים ואבחונים"}, {"tag": "h2", "content": "מדריכים על טעימות ראשונות, בדיקות אלרגיה לילדים וזכויות ילד אלרגי בישראל, בשפה פשוטה ומבוססת מחקר.", "heading": "מדריכים להורים"}, {"tag": "h2", "content": "מתי כדאי לקחת ילד לבדיקת אלרגיה, מה ההבדל בין אלרגיה לרגישות למזון, ואיך מתבצעת בדיקת אלרגיה.", "heading": "שאלות נפוצות"}, {"tag": "h2", "content": "מרגישים שהילד מגיב למזון, עקיצה או תרופה? אבחון מוקדם ומדויק יכול לשנות את ההתנהלות היומיומית ולהעניק שקט נפשי.", "heading": "קביעת תור לאבחון"}]'::jsonb
